contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address account, uint256 amount) public {
        // drive the public entry oracle(args) — here already satisfied: we exercise state via public views
        UFixed18 amt = UFixed18.wrap(amount);

        // read before observable state for a fresh account (deploy fresh c => no prior state)
        UFixed18 mBefore = c.maintenanceNext(account);
        bool reverted;
        try c.openTakeFor(account, amt) { reverted = false; } catch { reverted = true; }

        if (reverted) {
            // if the call reverted, no state change rule does not apply
            assert(mBefore == UFixed18.wrap(0));
        } else {
            // successful openTakeFor must not make an account liquidating
            assert(c.isLiquidating(account) == false);
        }
    }

    receive() external payable {}
}

